import sys

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1

    foods = [[], [], []]
    for _ in range(N):
        v = int(data[idx]) - 1; idx += 1
        a = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        foods[v].append((a, c))

    def compute_dp(items):
        dp = [0] * (X + 1)
        for a, c in items:
            if c > X:
                continue
            for j in range(X, c - 1, -1):
                nv = dp[j - c] + a
                if nv > dp[j]:
                    dp[j] = nv
        for i in range(1, X + 1):
            if dp[i] < dp[i - 1]:
                dp[i] = dp[i - 1]
        return dp

    dp0 = compute_dp(foods[0])
    dp1 = compute_dp(foods[1])
    dp2 = compute_dp(foods[2])

    ans = 0
    for c1 in range(X + 1):
        d1 = dp0[c1]
        if d1 <= ans:
            continue
        rem = X - c1
        for c2 in range(rem + 1):
            d2 = dp1[c2]
            if d2 <= ans:
                continue
            d3 = dp2[rem - c2]
            if d3 > ans:
                m = d1 if d1 < d2 else d2
                if d3 < m:
                    m = d3
                if m > ans:
                    ans = m

    print(ans)

main()

