import sys
from collections import defaultdict

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    A = [int(x) for x in data[1:N+1]]

    pos = defaultdict(list)
    for i, v in enumerate(A):
        pos[v].append(i)

    total = N * (N + 1) // 2

    def count_missing(positions):
        res = 0
        prev = -1
        for p in positions:
            g = p - prev - 1
            res += g * (g + 1) // 2
            prev = p
        g = N - prev - 1
        res += g * (g + 1) // 2
        return res

    def merge_sorted(a, b):
        result = []
        i, j = 0, 0
        la, lb = len(a), len(b)
        while i < la and j < lb:
            if a[i] <= b[j]:
                result.append(a[i])
                i += 1
            else:
                result.append(b[j])
                j += 1
        if i < la:
            result.extend(a[i:])
        if j < lb:
            result.extend(b[j:])
        return result

    miss = {}
    for v in pos:
        miss[v] = count_missing(pos[v])

    sum_distinct = 0
    for v in pos:
        sum_distinct += total - miss[v]

    sum_adj = 0
    for v in range(1, N):
        if v in pos and (v + 1) in pos:
            merged = merge_sorted(pos[v], pos[v + 1])
            mb = count_missing(merged)
            sum_adj += total - miss[v] - miss[v + 1] + mb

    print(sum_distinct - sum_adj)

solve()

import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1

    dice = []
    for _ in range(N):
        K = int(data[idx]); idx += 1
        faces = []
        for _ in range(K):
            faces.append(int(data[idx])); idx += 1
        dice.append(faces)

    counters = [Counter(d) for d in dice]
    Ks = [len(d) for d in dice]

    max_prob = 0.0
    for i in range(N):
        for j in range(i + 1, N):
            ci, cj = counters[i], counters[j]
            overlap = 0
            # Iterate over the smaller counter for efficiency
            if len(ci) <= len(cj):
                for v, c in ci.items():
                    if v in cj:
                        overlap += c * cj[v]
            else:
                for v, c in cj.items():
                    if v in ci:
                        overlap += c * ci[v]

            prob = overlap / (Ks[i] * Ks[j])
            if prob > max_prob:
                max_prob = prob

    print(max_prob)

main()

import sys
input = sys.stdin.readline

def main():
    N, M = map(int, input().split())

    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    redundant = 0
    for _ in range(M):
        u, v = map(int, input().split())
        if not union(u, v):
            redundant += 1

    print(redundant)

main()

